require_method('POST');require_csrf();$d=request_json();$bid=business_scope($u,(int)($d['business_id']??0));$url=trim((string)($d['file_url']??''));if(!filter_var($url,FILTER_VALIDATE_URL))json_response(['ok'=>false,'error'=>'A public image URL is required'],422);$type=in_array(($d['asset_type']??'photo'),['photo','cover','profile'],true)?$d['asset_type']:'photo';$st=db()->prepare('INSERT INTO gmb_assets(business_id,asset_type,file_url,caption) VALUES(?,?,?,?)');$st->execute([$bid,$type,$url,trim((string)($d['caption']??''))?:null]);audit((int)$u['id'],$bid,'gmb_asset_saved',['asset_id'=>(int)db()->lastInsertId()]);json_response(['ok'=>true]);
